import {createRound,advanceRound,inputRound,roundPayout,gameNames,gamePrices} from './leisure-games.js';
import {escapeHTML as h,button,roundHTML,resultHTML,drawRound,drawMarket,gameInstructions,gameRewards} from './leisure-view.js';
import {karaokeTracks,karaokeTrack,songTime} from './karaoke-tracks.js';
import {KaraokeAudio} from './karaoke-audio.js';

import {stocks,createMarket,restoreMarket,advanceMarket,applyMarketEvent} from './stock-market.js';
export {stocks} from './stock-market.js';
const positionChoices={quarter:{ratio:.25,label:'1/4 仓'},half:{ratio:.5,label:'半仓'},all:{ratio:1,label:'全仓'}};
const fresh=()=>({version:1,clock:0,rounds:0,highScores:{},visits:{},friends:{},account:{opened:false,openedAt:0},holdings:{},trades:[],prizes:[],buffs:{regenUntil:0,relaxedUntil:0},forum:{read:[],replies:{},lastReply:-180,checkinDay:-1},market:createMarket(),activeRound:null});
export const newCityLeisureState=fresh;
const animated=new Set(['karaoke','rhythm','race','claw','breaker','massage']);
const directions={KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right',KeyW:'up',ArrowUp:'up',KeyS:'down',ArrowDown:'down'};
const copy=v=>JSON.parse(JSON.stringify(v));
const yuan=n=>Number(n).toFixed(2);
export class CityLeisure{
 constructor(api){this.api=api;this.data=fresh();this.panel=null;this.mode='menu';this.controls={};this.softPaused=false;this.saveTime=0;this.track=0;this.stock=stocks[0].id;this.quantity=1;this.message='';this.result=null;this.lastPulse=-1;this.down=new Map();this.keyDown=new Map();this.canvasDirty=false;this.marketSaveTime=0;
  this.tradingButton=document.querySelector('#stockToggle');this.tradingButton.onclick=()=>this.openTrading();
  this.root=document.querySelector('#leisurePanel');this.content=document.querySelector('#leisureContent');this.root.addEventListener('click',e=>{const b=e.target.closest?.('[data-leisure]');if(!b||b.disabled)return;if(this.lastLaneTap?.button===b&&performance.now()-this.lastLaneTap.at<500){this.lastLaneTap=null;return;}if(!b.dataset.leisure.startsWith('hold:'))this.action(b.dataset.leisure);});
  this.root.addEventListener('pointerdown',e=>{const b=e.target.closest?.('[data-leisure]');if(!b||b.disabled||this.mode!=='game'||this.softPaused)return;if(b.dataset.leisure.startsWith('lane:')){e.preventDefault();this.lastLaneTap={button:b,at:performance.now()};this.action(b.dataset.leisure);}if(b.dataset.leisure.startsWith('hold:')){const c=b.dataset.leisure.slice(5);if(!['left','right','up','down'].includes(c))return;e.preventDefault();this.down.set(e.pointerId,c);this.syncControls();b.setPointerCapture?.(e.pointerId);this.api.refresh();}});
  const release=e=>{if(this.down.delete(e.pointerId)){this.syncControls();this.api.refresh();}};this.root.addEventListener('pointerup',release);this.root.addEventListener('pointercancel',release);this.root.addEventListener('lostpointercapture',release);
  document.querySelector('#leisureClose').onclick=()=>this.close();
  this.music=new KaraokeAudio({changed:()=>{this.updateMusicView();this.api.refresh();}});
 }
 syncControls(){this.controls=Object.fromEntries(['left','right','up','down'].map(c=>[c,[...this.down.values(),...this.keyDown.values()].includes(c)]));}
 resetControls(){this.controls={};this.down.clear();this.keyDown.clear();this.lastLaneTap=null;this.canvasDirty=false;}
 buffStatus(){const b=this.data.buffs,t=this.data.clock;return [b.regenUntil>t?`${b.regenLabel||'缓慢恢复'} ${Math.ceil(b.regenUntil-t)}秒`:null,b.relaxedUntil>t?`舒缓 ${Math.ceil(b.relaxedUntil-t)}秒`:null].filter(Boolean).join(' · ');}
 serialize(){return copy(this.data);}
 restore(s){this.close(false);this.data=s?.version===1?{...fresh(),...copy(s)}:fresh();this.data.market=restoreMarket(s?.market,this.data.clock);this.data.account=s?.account?copy(s.account):{opened:!!(this.data.trades.length||Object.values(this.data.holdings).some(v=>v.qty>0)),openedAt:this.data.clock};this.mode='menu';this.result=null;this.resetControls();this.stock=stocks[0].id;this.quantity=1;this.message='';this.marketSaveTime=0;this.syncTradingButton();}
 near(){const s=this.api.get();if(!s.started||s.dead||s.driving||!s.interior||s.dialogueBusy)return null;const [x,y,z]=s.position;const p=this.api.points.filter(p=>p.room===s.interior&&Math.abs(y-.2-p.floor)<1.2&&Math.hypot(x-p.at[0],z-p.at[1])<2.8).sort((a,b)=>Math.hypot(x-a.at[0],z-a.at[1])-Math.hypot(x-b.at[0],z-b.at[1]))[0],exit=this.api.nearExit?.();return p&&(!exit||Math.hypot(x-p.at[0],z-p.at[1])<Math.hypot(x-exit.at[0],z-exit.at[1]))?p:null;}
 prompt(){const p=this.near();return p?'E · '+(p.kind==='stocks'&&!this.data.account.opened?'湘城证券 · 免费开户':p.name):'';}
 interact(){const p=this.near();if(!p)return false;this.open(p);return true;}
 canOpenTrading(){const s=this.api.get();return s.started&&!s.paused&&!s.dead&&!s.dialogueBusy&&!s.uiBlocked&&!this.panel;}
 syncTradingButton(){const s=this.api.get();this.tradingButton.classList.toggle('hidden',!s.started||!this.data.account.opened);this.tradingButton.disabled=!(this.panel?.kind==='stocks'||this.canOpenTrading());}
 openTrading(){if(this.panel?.kind==='stocks'){this.close();return true;}if(!this.canOpenTrading())return false;if(!this.data.account.opened){this.api.toast?.('先到湘城证券营业部开户，即可随时交易。');return false;}return this.showPanel({id:'portable_stocks',room:this.api.get().interior,kind:'stocks',name:'湘城证券 · 随身交易',remote:true});}
 openAccount(){if(this.panel?.kind!=='stocks'||this.panel.remote||this.api.get().interior!==this.panel.room||this.panel.room!=='c4_securities')return false;if(!this.data.account.opened){this.data.account={opened:true,openedAt:this.data.market.clock};this.message='开户成功 · 按 V 或点击「交易」随时查看行情。';this.save();}this.syncTradingButton();this.render();return true;}
 open(p){if(!p||p.remote||this.api.get().interior!==p.room)return false;return this.showPanel(p);}
 showPanel(p){if(this.panel)this.close();this.api.closeOther?.();this.panel=p;this.mode='menu';this.message='';this.result=null;this.softPaused=false;this.resetControls();if(!p.remote)this.data.visits[p.room]=(this.data.visits[p.room]||0)+1;this.api.modal(true,p);this.root.classList.remove('hidden');this.render();if(p.kind==='stocks'&&this.data.account.opened)this.api.event?.('stockView',{stock:this.stock});this.save();return true;}
 close(save=true){this.music?.stop();if(!this.panel)return;this.resetControls();if(save)this.save();this.root.classList.add('hidden');this.panel=null;this.mode='menu';this.result=null;this.api.modal(false);}
 save(){this.api.save();}
 pay(n){const money=this.api.get().money;if(!Number.isFinite(n)||n<0||money+1e-8<n){this.message='钱不够了，可以先返回街区。';return false;}this.api.cash(-n);return true;}
 canPlay(type){return !!(Object.hasOwn(gameNames,type)&&this.panel&&this.panel.kind===type);}
 startGame(type){if(!this.canPlay(type))return false;if(this.data.activeRound){this.message='有一局尚未结束。先继续或结束它，再开新局。';this.render();return false;}const sponsored=!!this.api.sponsorGame?.(type,this.panel.room);if(!sponsored&&!this.pay(gamePrices[type])){this.render();return false;}const a=createRound(type,++this.data.rounds*104729+17,this.track);a.room=this.panel.room;a.station=this.panel.id;if(sponsored)a.paid=0;this.music.stop();this.data.activeRound=a;this.mode='game';this.lastPulse=-1;this.softPaused=false;this.result=null;this.resetControls();this.saveTime=0;if(type==='karaoke'){this.music.beginRound(a);this.syncAudio();}this.save();this.render();return true;}
 action(action){if(!this.panel)return false;const [cmd,arg]=String(action).split(':');const a=this.data.activeRound;
  if(cmd==='open-account')return this.openAccount();
  if(cmd==='close'){this.close();return true;}
  if(cmd==='menu'){this.music.stop();this.mode='menu';this.resetControls();this.render();this.save();return true;}
  if(cmd==='track'&&this.panel.kind==='karaoke'&&this.mode==='menu'){this.music.stop();this.track=Math.max(0,Math.min(2,Number(arg)||0));this.render();return true;}
  if(cmd==='listen'&&this.panel.kind==='karaoke'&&this.mode==='menu'){this.music.toggleListen(this.track);this.syncAudio();this.updateMusicView();return true;}
  if(cmd==='retry-audio'&&this.mode==='game'&&a?.type==='karaoke'&&!this.softPaused){this.music.beginRound(a);this.syncAudio();return true;}
  if(cmd==='start')return this.startGame(arg);
  if(cmd==='again'){if(this.result?.a.type==='massage')this.action(this.result.a.service==='body'?'massage:body':'massage:foot');else {if(this.result?.a.type==='karaoke')this.track=this.result.a.track;this.startGame(this.result?.a.type);}return true;}
  if(cmd==='resume'){if(a?.room===this.panel.room){this.mode='game';this.softPaused=false;this.resetControls();if(a.type==='karaoke')this.track=a.track;this.lastPulse=Math.floor((a.time-2)/(60/(a.bpm||120)));if(a.type==='karaoke'){this.music.beginRound(a);this.syncAudio();}this.render();return true;}return false;}
  if(cmd==='abandon'){if(a?.room!==this.panel.room)return false;a.done=true;if(a.type==='poker')a.folded=true;this.finish(true);return true;}
  if(cmd==='pause'){this.softPaused=!this.softPaused;this.resetControls();if(a?.type==='karaoke'){if(this.softPaused)this.music.pause();else this.music.beginRound(a);this.syncAudio();}this.save();this.render();return true;}
  if(cmd==='drink'&&this.panel.kind==='bar'){const drinks={beer:[12,20,90,'微醺','麦香啤酒'],cocktail:[22,35,150,'微醺','湘江晚风'],soda:[8,12,60,'舒缓','青柠汽水']},d=drinks[arg];if(!d)return false;const sponsored=!!this.api.sponsorGame?.('drink',this.panel.room);if(sponsored||this.pay(d[0])){this.api.heal(d[1]);this.data.buffs.regenUntil=Math.max(this.data.buffs.regenUntil,this.data.clock+d[2]);this.data.buffs.regenLabel=d[3];this.api.drink?.();this.message=`${d[4]}到手${sponsored?' · 练练请客':''} · 生命 +${d[1]} · ${d[2]} 秒缓慢恢复`;this.api.event?.('leisureDrink',{room:this.panel.room,drink:arg});}this.save();this.render();return true;}
  if(cmd==='talk'&&this.panel.kind==='social'){const id=this.panel.person,old=this.data.friends[id]||{level:0,last:-60};if(this.data.clock-old.last<60)this.message='刚聊过一轮，先逛逛吧。';else{old.level++;old.last=this.data.clock;this.data.friends[id]=old;this.message=(id==='alan'?['“往里面坐一点，门口老有人进进出出。杯子给你放这儿，我忙完这桌再来。你今天怎么像走了一晚上？”','“练练说赛车比开真车省心，输了又怪座椅不合适。老板真搬了张凳子来，他反倒不说话了。下回你跟他玩，先把座椅问好。”','“吧台刚擦完，别把袖子往上搁。平和堂那边最近有几件衣服挺好看，你有空去看看。总穿这件，我还以为你每天都没回家。”']:['“昨天按完脚，走出来轻快得很，今天才发现包没背。刚回店里，老板还说怎么这么快又来了。我说这次能不能只让我带包走。”','“牌馆那边今天挺热闹。上回有人拿着扑克牌喊碰，老板笑了半天，台费都忘了收。你要是过去，别替他把这一招教给别人。”','“我以前赚了一点就想请客，后来发现自己还没卖，饭钱倒已经付了。现在看看就好。手机能买卖也方便，方便得我都不敢老拿出来。”'])[(old.level-1)%3]+` · 熟悉度 ${old.level}`;}this.save();this.render();return true;}
  if(cmd==='massage'&&this.panel.kind==='massage'){if(this.data.activeRound){this.message='先继续或结束上一项服务。';this.render();return false;}const body=arg==='body',price=body?45:20;if(!this.pay(price)){this.render();return false;}this.data.activeRound={type:'massage',room:this.panel.room,station:this.panel.id,time:0,duration:5,score:0,paid:price,done:false,service:body?'body':'foot',heal:body?100:45};this.mode='game';this.softPaused=false;this.saveTime=0;this.save();this.render();return true;}
  if(cmd==='stock'&&this.panel.kind==='stocks'){if(stocks.some(s=>s.id===arg)){this.stock=arg;if(this.data.account.opened)this.api.event?.('stockView',{stock:arg});}this.render();this.save();return true;}
  if(cmd==='qty'&&this.panel.kind==='stocks'){if([1,5,10].includes(Number(arg)))this.quantity=Number(arg);else if(Object.hasOwn(positionChoices,arg))this.quantity=arg;else return false;this.render();return true;}
  if(['buy','sell'].includes(cmd)&&this.panel.kind==='stocks')return this.trade(cmd);
  if(cmd==='read'&&this.panel.kind==='net'){const posts=this.posts(),post=posts.find(p=>p.id===arg);if(!post)return false;if(!this.data.forum.read.includes(arg))this.data.forum.read.push(arg);this.message=post.body;this.save();this.render();return true;}
  if(cmd==='reply'&&this.panel.kind==='net'){if(!['hello','tip'].includes(arg))return false;if(this.data.clock-this.data.forum.lastReply<180)this.message='刚发过帖，先出去走走再回来。';else{this.data.forum.lastReply=this.data.clock;this.data.forum.replies[arg]=(this.data.forum.replies[arg]||0)+1;this.api.cash(2);this.message=(arg==='hello'?'“下班后来碰头，先去打两把街机！”':'“优衣库换装、足浴回血、外围道路开车，都记下了。”')+' · 获得活跃奖励 ¥2';}this.save();this.render();return true;}
  if(cmd==='checkin'&&this.panel.kind==='net'){const day=Math.floor(this.data.clock/1200);if(this.data.forum.checkinDay===day)this.message='本日已签到。街区游玩 20 分钟后开始下一日。';else{this.data.forum.checkinDay=day;this.api.cash(6);this.message='街区论坛签到成功 · ¥6';}this.save();this.render();return true;}
  if(this.mode!=='game'||!a||a.room!==this.panel.room||this.softPaused)return false;
  if(cmd==='lane'){if(a.type==='karaoke'){if(!this.music.ready(a))return false;advanceRound(a,.001,this.controls,this.music.time(a));if(a.done){this.finish();return false;}}const ok=inputRound(a,'lane',Number(arg));if(ok&&a.type!=='karaoke')this.api.tone?.([261.63,329.63,392,523.25][Number(arg)],.11,'triangle',.024);this.updateStatus();return ok;}
  if(cmd==='shoot'){inputRound(a,a.type==='claw'?'drop':'shoot');this.save();this.api.refresh();return true;}
  if(cmd==='discard'||cmd==='hu'){inputRound(a,cmd,Number(arg));if(a.done)this.finish();else{this.save();this.render();}return true;}
  if(cmd.startsWith('poker-')&&a.type==='poker'){
   if(cmd==='poker-fold')inputRound(a,'fold');else if(cmd==='poker-call'||cmd==='poker-raise'){const raised=cmd==='poker-raise',cost=a.toCall+(raised?5:0);if(!this.pay(cost)){this.render();return false;}a.paid+=cost;a.pot+=cost+(raised?5:0);a.toCall=0;inputRound(a,'advance');}else return false;
   if(a.done)this.finish();else{this.save();this.render();}return true;
  }return false;
 }
 orderQuantity(side){if(!['buy','sell'].includes(side))return 0;if([1,5,10].includes(this.quantity))return this.quantity;if(!Object.hasOwn(positionChoices,this.quantity))return 0;const price=this.data.market.prices[this.stock],hold=this.data.holdings[this.stock]||{qty:0,cost:0},ratio=positionChoices[this.quantity].ratio;if(!Number.isFinite(price)||price<=0)return 0;
  if(side==='sell')return Math.floor(hold.qty*ratio);const affordable=Math.floor(Math.round(this.api.get().money*100)/Math.round(price*100));return Math.min(10000-hold.qty,Math.floor(affordable*ratio));
 }
 trade(side){if(this.panel?.kind!=='stocks'||!this.data.account.opened||!['buy','sell'].includes(side))return false;const item=stocks.find(s=>s.id===this.stock),price=this.data.market.prices[item?.id],qty=this.orderQuantity(side),hold=this.data.holdings[item?.id]||{qty:0,cost:0};if(!item)return false;if(qty<1){this.message=side==='buy'?'该比例不足买入 1 股，或已达持仓上限。':'该比例不足卖出 1 股。';this.render();return false;}if(hold.qty+qty>10000&&side==='buy'){this.message='该股票持仓已达上限。';this.render();return false;}
  const amount=Math.round(price*qty*100)/100;if(side==='buy'){if(!this.pay(amount)){this.render();return false;}hold.qty+=qty;hold.cost=Math.round((hold.cost+amount)*100)/100;this.message=`买入 ${item.name} ${qty} 股 · ¥${yuan(amount)}`;}
  else{if(hold.qty<qty){this.message='持仓不足，请减少卖出数量。';this.render();return false;}const cost=hold.cost*qty/hold.qty;hold.cost=Math.round((hold.cost-cost)*100)/100;hold.qty-=qty;this.api.cash(amount);this.message=`卖出 ${item.name} ${qty} 股 · ¥${yuan(amount)} · 本次收益 ${amount-cost>=0?'+':''}¥${yuan(amount-cost)}`;if(!hold.qty)hold.cost=0;}
  this.data.holdings[item.id]=hold;this.data.trades.push({stock:item.id,side,qty,price,at:this.data.clock});this.data.trades=this.data.trades.slice(-30);this.save();this.render();return true;
 }
 applyMarketEvent(event){const applied=applyMarketEvent(this.data.market,event);if(applied){this.save();if(this.panel?.kind==='stocks'&&this.data.account.opened)this.updateMarketView();}return applied;}
 marketTick(dt){return advanceMarket(this.data.market,dt,this.api.get().chapterProgress||0);}
 tick(dt){this.syncAudio();const s=this.api.get(),playing=s.started&&!s.paused&&!s.dead&&!document.hidden,watching=s.started&&!s.dead&&!document.hidden&&this.panel?.kind==='stocks'&&this.data.account.opened;if((document.hidden||s.dead||!s.started)&&this.music.wanted)this.music.pause();if(this.panel&&!this.softPaused&&!document.hidden&&!s.dead)this.music.watch(dt);
  if(playing){this.data.clock+=dt;if(this.data.buffs.regenUntil>this.data.clock)this.api.heal(dt*.35);if(this.data.buffs.relaxedUntil>this.data.clock)this.api.heal(dt*.2);}
  if(playing||watching){const changed=this.marketTick(dt);this.marketSaveTime+=dt;if(changed&&watching)this.updateMarketView();if(this.marketSaveTime>=5){this.marketSaveTime=0;this.save();}}
  const a=this.data.activeRound;if(!this.panel||this.mode!=='game'||!a||this.softPaused||document.hidden||s.dead)return;const wasMoving=a.moving;
  if(a.type==='massage'){a.time+=dt;if(a.time>=a.duration)a.done=true;}else advanceRound(a,dt,this.controls,a.type==='karaoke'?this.music.time(a):undefined);
  if(a.type==='rhythm'){const pulse=Math.floor((a.time-2)/(60/a.bpm));if(pulse>=0&&pulse>this.lastPulse&&pulse<a.notes.length){this.lastPulse=pulse;const melody=[261.63,293.66,329.63,392,440,392,329.63,293.66];this.api.tone?.(melody[(pulse+a.track*2)%8],.16,'sine',.018);}}
  if(a.done){this.finish();return;}if(wasMoving&&!a.moving){this.save();this.render();return;}if(this.needsFrame()){drawRound(this.ctx,a);this.canvasDirty=false;this.updateStatus();this.saveTime+=dt;if(this.saveTime>=2){this.saveTime=0;this.save();}}
 }
 finish(abandoned=false){const a=this.data.activeRound;if(!a)return;this.music.stop();this.data.activeRound=null;const payout=abandoned?0:roundPayout(a);if(a.type==='massage'&&!abandoned){this.api.heal(a.heal);this.data.buffs.relaxedUntil=this.data.clock+180;this.data.buffs.label='舒缓';a.feedback=['“先别急着穿鞋，这边还没按完。你刚才说只走了一点路，这脚可不像一点。坐稳，我手重了就说，别硬撑着不出声。”','“好了，慢点起来，先走两步试试。水还给你留着呢，喝完再出去。你每回来都像外面有人等，坐一会儿也不耽误那几步路。”','“肩膀怎么一直绷着？你看我，往下放一点，对，就这样。门口有人我会喊你，这会儿不用自己隔两秒就回一次头。”'][(this.data.visits[a.room]||0)%3];}
  if(payout)this.api.cash(payout);if(!abandoned&&a.type==='claw'&&a.caught>=0){this.data.prizes.push({id:'crowned_dolphin',at:this.data.clock});this.data.prizes=this.data.prizes.slice(-50);}const best=this.data.highScores[a.type]||{score:0,plays:0,earned:0};best.score=Math.max(best.score,a.score||0);best.plays++;best.earned+=payout-a.paid;this.data.highScores[a.type]=best;this.result={a:copy(a),payout,abandoned};this.api.event?.('leisureFinish',{room:a.room,type:a.type,score:a.score||0,hits:a.hits||0,abandoned});this.mode='result';this.resetControls();this.save();this.render();
 }
 needsFrame(){if(this.panel?.kind==='stocks'&&this.data.account.opened&&!document.hidden)return true;const a=this.data.activeRound;return !!(this.panel&&this.mode==='game'&&!this.softPaused&&a&&(this.canvasDirty||animated.has(a.type)||a.type==='billiards'&&(a.moving||this.controls.left||this.controls.right)));}
 onBlur(){if(this.music.mode)this.music.pause();if(this.panel?.kind==='stocks'){this.resetControls();this.save();return;}if(this.panel&&this.mode==='game'){this.softPaused=true;this.resetControls();this.save();this.render();}}
 syncAudio(){this.music.mute(this.api.audioEnabled?.()===false);}
 updateMusicView(){if(this.panel?.kind!=='karaoke')return;const status=document.querySelector('#karaokeAudioStatus');if(status)status.textContent=this.music.status();const listen=document.querySelector('#karaokeListen');if(listen)listen.textContent=this.music.mode==='listen'&&this.music.wanted?'暂停全曲':this.music.mode==='listen'&&this.music.state==='paused'?'继续全曲':this.music.state==='blocked'||this.music.state==='error'?'重试播放':'播放全曲';const retry=document.querySelector('#karaokeRetry');if(retry)retry.classList.toggle('hidden',!['blocked','error'].includes(this.music.state));}
 handleKey(e,down){if(!this.panel)return false;if(this.panel.kind==='stocks'&&['Enter','Space'].includes(e.code)&&e.target?.closest?.('[data-leisure],#leisureClose'))return true;if(e.code==='Tab'||e.target?.id==='leisurePower'&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.code))return true;e.preventDefault?.();if(!down){if(this.keyDown.delete(e.code)){this.syncControls();this.api.refresh();}return true;}if(e.repeat)return true;if(e.code==='Escape'||e.code==='KeyV'&&this.panel.kind==='stocks'){this.close();return true;}if(this.mode!=='game')return true;if(e.code==='KeyP'){this.action('pause');return true;}if(this.softPaused)return true;const a=this.data.activeRound;if(!a)return true;
  if(a.type==='karaoke'||a.type==='rhythm'){const lane=['KeyD','KeyF','KeyJ','KeyK'].indexOf(e.code);if(lane>=0)this.action('lane:'+lane);}
  else if(['race','claw','breaker','billiards'].includes(a.type)){const c=directions[e.code];if(c){this.keyDown.set(e.code,c);this.syncControls();this.api.refresh();}if(e.code==='Space')this.action('shoot');}
  else if(a.type==='poker'){const cmd={KeyC:'poker-call',KeyR:'poker-raise',KeyF:'poker-fold'}[e.code];if(cmd)this.action(cmd);}else if(a.type==='mahjong'){if(/^Digit[1-8]$/.test(e.code))this.action('discard:'+(Number(e.code.slice(5))-1));if(e.code==='KeyH')this.action('hu');}return true;
 }
 posts(){return [{id:'welcome',title:'放学以后 · 回来聚一聚',body:'好久没回这边，南门口那家米粉还在。约了朋友去解放西，结果路过天蝎电玩又坐了一盘，饭倒没顾上吃。有人出来聚吗？别又说改天。'},
 {id:'market',title:'商圈消息 · '+this.data.market.event,body:'我在湘城证券开的户，没花钱，现在手机就能看，不用天天跑营业部。这几天江湾和星潮的动静凑得太齐，有人说这两家公司借了不少钱，却还在往外搬东西。到底发生了什么，谁知道？别转那张糊得连公司名都看不清的图了。'},
 {id:'roads',title:'开车绕步行街 · 停车攻略',body:'别学我，把车开到步行街口才想起来这里进不去。书院路先停好，腿走进去反而快；要绕到五一就走外围车道。东北连接路现在也通了，回北辰不用再兜那么大一圈。'},
 {id:'friends',title:'常客留言 · 今晚去哪儿',body:`你已经玩了 ${Object.values(this.data.highScores).reduce((n,s)=>n+s.plays,0)} 局，收藏 ${this.data.prizes.length} 只街机小玩偶。练练说‘就坐一会儿’，我看这又是天亮才回家的架势。老位置给你留着，别在门口看半天又走了。`}];}
 menuHTML(){const kind=this.panel.kind,sponsored=!!this.api.sponsorGame?.(kind==='bar'?'drink':kind,this.panel.room),a=this.data.activeRound,best=this.data.highScores[kind],saved=a?.room===this.panel.room?`<div class="savedRound"><b>上次的${a.type==='karaoke'?'《'+h(karaokeTrack(a.track).name)+'》':gameNames[a.type]||'恢复服务'}还在</b>${button('resume','继续 · 已付费')}${button('abandon','结束本局 · 放弃奖励')}</div>`:a?'<p class="leisureHelp">还有一局留在其他场所，回到那里可以继续。</p>':'';
  let content='';if(gameNames[kind])content=`${kind==='karaoke'?`<div class="leisureActionRow">${karaokeTracks.map((t,i)=>button('track:'+i,(i===this.track?'● ':'')+t.name,false,i===this.track?'selected':'')).join('')}</div>`:''}<h3>${gameNames[kind]}</h3><p class="leisureHelp">${h(gameInstructions(kind))}</p><p>${h(gameRewards[kind])}</p><p>${kind==='karaoke'?`豚师原创《${h(karaokeTrack(this.track).name)}》 · 全曲 ${songTime(karaokeTrack(this.track).duration)} · 挑战约 ${Math.ceil(karaokeTrack(this.track).beats.at(-1)+1)} 秒`:'短局即开即玩，退出后可以继续。'}</p>${kind==='karaoke'?'<div class="leisureActionRow"><button id="karaokeListen" data-leisure="listen">播放全曲</button></div><p id="karaokeAudioStatus" class="leisureHelp" role="status"></p>':''}${button('start:'+kind,sponsored?'开始 · 练练请客':`开始 · ¥${gamePrices[kind]}`,!!a,'leisurePrimary')}<p>最高成绩 ${best?.score||0} · 已玩 ${best?.plays||0} 局 · 累计净额 ¥${yuan(best?.earned||0)}</p>${kind==='claw'?`<p>收藏册 · 王冠海豚 ${this.data.prizes.length} 只</p>`:''}`;
  else if(kind==='bar')content=`<h3>今晚喝点什么</h3><div class="venueOptions">${button('drink:beer','麦香啤酒 · ¥12 · 生命 +20 / 微醺 90秒')}${button('drink:cocktail','湘江晚风 · ¥22 · 生命 +35 / 微醺 150秒')}${button('drink:soda','青柠汽水 · ¥8 · 生命 +12 / 舒缓 60秒')}</div><p>微醺 / 舒缓期间每秒再恢复少量生命。生命上限 100。</p>`;
  else if(kind==='social')content=`<h3>${h(this.panel.name.split(' · ')[0])}</h3><p>熟悉度 ${this.data.friends[this.panel.person]?.level||0}</p>${button('talk','聊两句')}<p>熟人隔一会儿会换个话题。</p>`;
  else if(kind==='massage')content=`<h3>坐下，缓一缓</h3><div class="venueOptions">${button('massage:foot','足浴 · ¥20 · 生命 +45')}${button('massage:body','全身推拿 · ¥45 · 生命恢复至满')}</div><p>五秒恢复服务，结束后获得三分钟舒缓状态。</p>`;
  else if(kind==='net')content=`<h3>街区论坛 / 消息</h3><div class="forumPosts">${this.posts().map(p=>button('read:'+p.id,(this.data.forum.read.includes(p.id)?'已读 · ':'')+p.title)).join('')}</div><div class="leisureActionRow">${button('checkin','每日签到 · ¥6')}${button('reply:hello','发帖：今晚碰头')}${button('reply:tip','回帖：游玩攻略')}</div><p>有效发帖奖励 ¥2，每三分钟一次。阅读和回复都会保存。</p>`;
  else if(kind==='stocks')return this.data.account.opened?this.stocksHTML():`<h3>湘城证券 · 开户</h3><p>在营业部免费开户，开通随身交易。</p><p class="leisureHelp">开户后按 V，或点击屏幕上方的「交易」，即可随时查看行情、买卖股票。全部交易使用随身钱包。</p>${button('open-account','免费开户',false,'leisurePrimary')}`;return saved+content+(sponsored?'<p class="leisureHelp">这一局练练请客，完成即可拿到凭证；成绩会帮上后续行动。</p>':'')+(this.buffStatus()?`<p class="leisureHelp">当前状态 · ${h(this.buffStatus())} · 返回街区后计时</p>`: '');
 }
 stocksHTML(){const item=stocks.find(s=>s.id===this.stock);return `<div class="marketHeader"><span class="marketLive">实时行情</span><span id="marketQuoteTime"></span></div><p id="marketNews" class="marketNews"></p><div class="stockTabs">${stocks.map(s=>`<button data-leisure="stock:${s.id}" class="${s.id===this.stock?'selected':''}">${h(s.name)} <span id="stockQuote_${s.id}"></span></button>`).join('')}</div><div class="marketGrid"><div><canvas id="leisureChart" width="640" height="220" aria-label="${item.name}价格走势"></canvas></div><div class="marketOrder"><h3 id="stockCurrent"></h3><p id="stockHolding"></p><div class="leisureActionRow">${[1,5,10].map(n=>button('qty:'+n,n+' 股',false,n===this.quantity?'selected':'')).join('')}</div><div class="leisureActionRow stockPositions">${Object.entries(positionChoices).map(([id,p])=>button('qty:'+id,p.label,false,id===this.quantity?'selected':'')).join('')}</div><div class="stockOrders"><button id="stockBuy" data-leisure="buy"></button><button id="stockSell" data-leisure="sell"></button></div><p class="leisureHelp">买入按可用钱包比例，卖出按当前股票持仓比例，向下取整到 1 股。行情每秒更新，下单按点击时的最新价格与数量结算。</p></div></div><details><summary>最近交易</summary>${this.data.trades.slice(-6).reverse().map(t=>`<p>${stocks.find(s=>s.id===t.stock).name} · ${t.side==='buy'?'买入':'卖出'} ${t.qty} 股 @ ¥${yuan(t.price)}</p>`).join('')||'<p>暂无交易</p>'}</details>`;}
 updateMarketView(){if(this.panel?.kind!=='stocks'||!this.data.account.opened)return;const market=this.data.market,item=stocks.find(s=>s.id===this.stock),hold=this.data.holdings[item.id]||{qty:0,cost:0},price=market.prices[item.id],value=hold.qty*price,pnl=value-hold.cost;
  document.querySelector('#marketQuoteTime').textContent='报价 '+market.quote+' · 每秒更新';document.querySelector('#marketNews').textContent=market.event;
  for(const s of stocks)document.querySelector('#stockQuote_'+s.id).textContent='¥'+yuan(market.prices[s.id]);
  document.querySelector('#stockCurrent').textContent=item.name+' · ¥'+yuan(price);document.querySelector('#stockHolding').textContent=`持有 ${hold.qty} 股 · 均价 ¥${yuan(hold.qty?hold.cost/hold.qty:0)} · 成本 ¥${yuan(hold.cost)} · 市值 ¥${yuan(value)} · 浮动 ${pnl>=0?'+':''}¥${yuan(pnl)}`;
  const buy=document.querySelector('#stockBuy'),sell=document.querySelector('#stockSell'),buyQty=this.orderQuantity('buy'),sellQty=this.orderQuantity('sell');buy.textContent='买入 '+buyQty+' 股 · ¥'+yuan(price*buyQty);buy.disabled=buyQty<1||hold.qty+buyQty>10000||this.api.get().money+1e-8<Math.round(price*buyQty*100)/100;sell.textContent='卖出 '+sellQty+' 股 · ¥'+yuan(price*sellQty);sell.disabled=sellQty<1||hold.qty<sellQty;
  drawMarket(document.querySelector('#leisureChart').getContext('2d'),market.history[this.stock]);this.updateStatus();
 }
 render(){if(!this.panel)return;document.querySelector('#leisureTitle').textContent=this.panel.name;document.querySelector('#leisureWallet').textContent='钱包 ¥'+yuan(this.api.get().money);this.root.setAttribute('data-theme',this.panel.kind);this.content.classList.toggle('leisureGame',this.mode==='game');document.querySelector('#leisureNote').textContent=this.message;
  const a=this.data.activeRound;this.content.innerHTML=this.mode==='game'&&a?`${button('pause',this.softPaused?'继续 / P':'暂停 / P',false,'gamePause')}${this.softPaused?'<div class="gamePaused">已暂停 · 点击继续</div>':''}${roundHTML(a)}`:this.mode==='result'&&this.result?resultHTML(this.result.a,this.result.payout,this.result.abandoned)+`<p>${h(this.result.abandoned?'':this.result.a.feedback||'')}</p>`:this.menuHTML();
  this.ctx=null;if(this.mode==='game'&&a){const canvas=document.querySelector('#leisureCanvas');if(!['mahjong','poker'].includes(a.type)){this.ctx=canvas.getContext('2d');drawRound(this.ctx,a);this.canvasDirty=false;
   let aimPointer=null;
   const aim=e=>{if(this.softPaused||['karaoke','rhythm','massage'].includes(a.type))return;const rect=canvas.getBoundingClientRect();inputRound(a,'aim',{x:(e.clientX-rect.left)*640/rect.width,y:(e.clientY-rect.top)*360/rect.height});this.canvasDirty=true;this.api.refresh();};
   canvas.addEventListener('pointerdown',e=>{if(aimPointer!==null)return;aimPointer=e.pointerId;canvas.setPointerCapture?.(e.pointerId);aim(e);});
   canvas.addEventListener('pointermove',e=>{if(aimPointer===e.pointerId)aim(e);});
   const end=e=>{if(aimPointer!==e.pointerId)return;aimPointer=null;this.save();};
   canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);canvas.addEventListener('lostpointercapture',end);
   if(a.type==='billiards'){const power=document.querySelector('#leisurePower');power.oninput=e=>{if(this.softPaused||a.moving){e.target.value=Math.round(a.power*100);return;}inputRound(a,'power',Number(e.target.value)/100);this.canvasDirty=true;this.api.refresh();};power.onchange=()=>this.save();}}}
  if(this.mode==='menu'&&this.panel.kind==='stocks'&&this.data.account.opened)this.updateMarketView();this.updateMusicView();this.updateStatus();this.api.refresh();
 }
 updateStatus(){const a=this.data.activeRound;document.querySelector('#leisureStatus').textContent=this.mode==='game'&&a?`${gameNames[a.type]||'恢复服务'} · ${a.feedback||''} ${a.score?`· 得分 ${a.score}`:''}`:this.panel?.kind==='stocks'?'Esc / V 关闭 · 账户、持仓与钱包自动保存':'Esc / 返回街区 · 状态与钱包自动保存';document.querySelector('#leisureWallet').textContent='钱包 ¥'+yuan(this.api.get().money);}
}
